parameters.jsCode:
const lead = $('Fetch New Leads from Supabase').item.json;
const geminiRaw = $input.item.json.candidates[0].content.parts[0].text;
const aiData = JSON.parse(geminiRaw);

// Generate clean URL slug e.g. "chafa-cafe-baner"
const slug = (lead.name + '-' + lead.area)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '');

// 7 days demo expiration
const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

// Prepare sample photo list from raw references or curated fallbacks
const photoRefs = lead.raw_photo_references || [];
const photos = photoRefs.map(p => `https://places.googleapis.com/v1/${p.name}/media?maxHeightPx=1000&maxWidthPx=1400&key=${$env.GOOGLE_PLACES_API_KEY}`);
const heroImage = photos.length > 0 ? photos[0] : 'https://images.unsplash.com/photo-1554118811-1e0d58224f24?auto=format&fit=crop&w=1400&q=80';

const siteConfig = {
  slug: slug,
  lead_id: lead.id,
  restaurant: {
    name: lead.name,
    area: lead.area,
    tagline: aiData.tagline,
    about: aiData.about_story,
    phone: lead.national_phone_number,
    address: lead.formatted_address,
    maps_url: lead.google_maps_uri,
    usp: aiData.usp_bullets || []
  },
  theme: {
    archetype_id: aiData.recommended_archetype || 'artisanal-cafe',
    primary_color: aiData.primary_color || '#8B4513',
    accent_color: aiData.accent_color || '#D4A574'
  },
  assets: {
    hero_image: heroImage,
    photos: photos.slice(0, 6)
  },
  menu: aiData.curated_menu || [],
  reviews: aiData.top_reviews || [],
  pricing: {
    tier1_price: 7999,
    tier2_price: 14999,
    tier3_price: 29999,
    monthly_support: 1499,
    special_offer: 'Launch Offer: Free .in Domain + QR Standees if claimed within 7 days'
  },
  demo: {
    status: 'pending_review',
    expires_at: expiresAt,
    demo_url: `${$env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3000'}/s/${slug}`
  }
};

return [{ json: siteConfig }];
